-- Dienkripsi via NEXUS.ID Script Encryptor. Isi asli hanya terbaca saat dijalankan.
local nx_key = "VrDJ1i7I1VQ7e1D4"
local nx_data = ""
local nx_b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function nx_b64decode(data)
  data = data:gsub('[^'..nx_b64chars..'=]', '')
  local bytes = {}
  local buffer, bufbits = 0, 0
  for i = 1, #data do
    local c = data:sub(i,i)
    if c ~= '=' then
      local idx = nx_b64chars:find(c, 1, true) - 1
      buffer = buffer * 64 + idx
      bufbits = bufbits + 6
      if bufbits >= 8 then
        bufbits = bufbits - 8
        local shiftOut = math.floor(buffer / (2 ^ bufbits))
        bytes[#bytes + 1] = string.char(shiftOut % 256)
        buffer = buffer % (2 ^ bufbits)
      end
    end
  end
  return table.concat(bytes)
end
local function nx_xor(s, k)
  local out = {}
  for i = 1, #s do
    local kb = k:byte((i - 1) % #k + 1)
    out[i] = string.char(bit32.bxor(s:byte(i), kb))
  end
  return table.concat(out)
end
local nx_src = nx_xor(nx_b64decode(nx_data), nx_key)
local nx_fn, nx_err = loadstring(nx_src)
if not nx_fn then
  warn("NEXUS.ID decrypt error: " .. tostring(nx_err))
else
  nx_fn()
end
